#[test_only]
module protocol::liquidation_test {

  use sui::test_scenario;
  use sui::clock;

  use protocol::market_t::MainMarket;
  use protocol::oracle_t;
  use test_coin::eth::ETH;
  use protocol::open_obligation_t;
  use test_coin::usdc::USDC;
  use test_coin::usdt::USDT;
  use protocol::market_t::default_eth_decimal_places;
  use protocol::market_t::default_stable_decimal_places;
  use std::unit_test::assert_eq;

  const ADMIN: address = @0xAD;


  #[test]
  #[expected_failure(abort_code = protocol::error::Err_Caller_Not_Permitted, location = protocol::app)]
  public fun liquidator_not_whitelisted() {
    let borrower = @0xBB;
    let liquidator = @0xCC;

    let mut scenario_value = test_scenario::begin(ADMIN);
    let scenario = &mut scenario_value;
    let mut clock = clock::create_for_testing(scenario.ctx());

    let (admin_cap, mut app, mut market, coin_registry) = protocol::app_t::default_app_init<MainMarket>(
        scenario, 
        &mut clock, 
        ADMIN,
    );
    let mut x_oracle = oracle_t::init_t(scenario);
    clock.set_for_testing(200 * 1000);
    x_oracle.update_price<ETH>(&clock, oracle_t::calc_scaled_price(1000, 0)); // $1000
    x_oracle.update_price<USDT>(&clock, oracle_t::calc_scaled_price(1, 0)); // $1000

    let eth_coin = sui::coin::mint_for_testing<ETH>(1 * 10u64.pow(default_eth_decimal_places()), test_scenario::ctx(scenario));
    let usdt_coin = sui::coin::mint_for_testing<USDT>(1000 * 10u64.pow(default_stable_decimal_places()), test_scenario::ctx(scenario));

    scenario.next_tx(borrower);
    let obligation_owner_cap = open_obligation_t::open_obligation_t<MainMarket>(scenario, &app, &mut market);
    protocol::deposit::deposit<MainMarket, ETH>(&app, &mut market, &obligation_owner_cap, eth_coin, &clock, scenario.ctx());
    protocol::deposit::deposit<MainMarket, USDT>(&app, &mut market, &obligation_owner_cap, usdt_coin, &clock, scenario.ctx());

    x_oracle.update_price<USDC>(&clock, oracle_t::calc_scaled_price(1, 0)); // $1
    x_oracle.update_price<USDT>( &clock, oracle_t::calc_scaled_price(1, 0)); // $1
    x_oracle.update_price<ETH>( &clock, oracle_t::calc_scaled_price(1000, 0)); // $1000

    // collateral usd: 2000, debt: 699
    scenario.next_tx(borrower);
    let borrow_amount = 699 * 10u64.pow(default_stable_decimal_places());
    let borrowed = protocol::borrow::borrow<MainMarket, USDC>(&app, &obligation_owner_cap, &mut market, &coin_registry, borrow_amount, &x_oracle, &clock, scenario.ctx());
    std::unit_test::destroy(borrowed);

    scenario.next_tx(liquidator);
    let usdc_amount = 900 * 10u64.pow(default_stable_decimal_places());
    let usdc_coin = sui::coin::mint_for_testing<USDC>(usdc_amount, test_scenario::ctx(scenario));

    let permit = protocol::whitelist_admin::mint_new_whitelist(&admin_cap, &mut app, test_scenario::ctx(scenario));

    protocol::liquidate::liquidate<MainMarket, USDC, ETH>(
      &app,
      &permit,
      obligation_owner_cap.id(),
      &mut market, 
      usdc_coin, 
      &coin_registry,

